css:
@import url("https://fonts.googleapis.com/css2?family=Syne:wght@600;700;800&family=Manrope:wght@400;500;700&display=swap");
:root{--blue:#1F3BFF;--blue-d:#0B1470;--pink:#FFD6E0;--pink-d:#FF9FB6;--white:#fff;--paper:#F3F4FF;--text:#141A4A;--muted:#5B6190;
--display:"Syne",system-ui,sans-serif;--body:"Manrope",system-ui,-apple-system,"Segoe UI",sans-serif;--wrap:1280px}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;font-family:var(--body);font-size:17px;line-height:1.65;color:var(--text);background:var(--white);-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}a{color:inherit}p{margin:0 0 1em}
h1,h2,h3{font-family:var(--display);font-weight:800;margin:0;line-height:.98;letter-spacing:-.03em;color:var(--blue-d)}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 28px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--pink);padding:10px 14px;z-index:99}
:focus-visible{outline:3px solid var(--pink-d);outline-offset:3px}
.site-header{background:var(--blue);color:#fff}
.nav{display:flex;align-items:center;justify-content:space-between;height:84px}
.logo{font-family:var(--display);font-weight:800;font-size:26px;text-decoration:none;color:#fff;letter-spacing:-.02em}
.menu{display:flex;gap:34px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none;font-weight:500}.menu a:hover{color:var(--pink)}
.btn{display:inline-flex;align-items:center;gap:10px;padding:15px 28px;border-radius:999px;font-weight:700;text-decoration:none;border:2px solid transparent;font-family:var(--body);font-size:16px;cursor:pointer;transition:background .2s,color .2s}
.btn-pink{background:var(--pink);color:var(--blue-d)}.btn-pink:hover{background:#fff}
.btn-blue{background:var(--blue);color:#fff}.btn-blue:hover{background:var(--blue-d)}
.btn-ghost{border-color:#fff;color:#fff}.btn-ghost:hover{background:#fff;color:var(--blue)}
.burger{display:none;background:none;border:2px solid #fff;border-radius:999px;padding:8px 12px;cursor:pointer}.burger span{display:block;width:20px;height:2px;background:#fff;margin:4px 0}

.hero{background:var(--blue);color:#dfe4ff;padding:40px 0 0;overflow:hidden}
.hero h1{color:#fff;font-size:clamp(56px,11vw,188px);line-height:.88}
.hero h1 span{color:var(--pink);display:block}
.hero-foot{display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:end;margin-top:40px;padding-bottom:50px}
.hero-foot p{font-size:20px;max-width:46ch;margin:0}
.hero-actions{display:flex;gap:12px;flex-wrap:wrap;justify-content:flex-end}
.strip{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:14px}
.strip img{width:100%;height:340px;object-fit:cover;border-radius:24px 24px 0 0}

.clients{background:var(--pink);padding:26px 0}
.clients .wrap{display:flex;justify-content:space-between;align-items:center;gap:30px;flex-wrap:wrap}
.clients p{margin:0;font-weight:700;color:var(--blue-d)}
.clients .row{display:flex;gap:44px;flex-wrap:wrap}.clients .row span{font-family:var(--display);font-weight:700;font-size:22px;color:var(--blue-d)}

section{padding:120px 0}
.head{display:flex;justify-content:space-between;align-items:end;gap:40px;margin-bottom:56px;flex-wrap:wrap}
.head h2{font-size:clamp(44px,6.4vw,96px)}
.head p{max-width:42ch;color:var(--muted);font-size:18px;margin:0}

.work{display:grid;grid-template-columns:repeat(12,1fr);gap:26px}
.project{text-decoration:none;display:block}
.project figure{margin:0;border-radius:26px;overflow:hidden;background:var(--paper)}
.project img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
.project:hover img{transform:scale(1.05)}
.project .meta{display:flex;justify-content:space-between;gap:12px;margin-top:16px;align-items:baseline}
.project h3{font-size:30px}
.project span{color:var(--muted);font-size:15px}
.p1{grid-column:1/8}.p1 figure{aspect-ratio:4/3}
.p2{grid-column:8/13;margin-top:120px}.p2 figure{aspect-ratio:4/5}
.p3{grid-column:1/6}.p3 figure{aspect-ratio:4/5}
.p4{grid-column:6/13;margin-top:80px}.p4 figure{aspect-ratio:4/3}

.services{background:var(--paper)}
.svc-list{border-top:2px solid var(--blue-d)}
.svc-row{display:grid;grid-template-columns:1.1fr 1.4fr .9fr;gap:40px;padding:34px 0;border-bottom:2px solid var(--blue-d);align-items:start}
.svc-row h3{font-size:clamp(30px,3.4vw,48px)}
.svc-row p{margin:0;color:var(--muted)}
.svc-row ul{list-style:none;padding:0;margin:0;font-weight:700;color:var(--blue)}
.svc-row li{margin-bottom:4px}

.big-quote{background:var(--blue);color:#fff}
.big-quote blockquote{margin:0}
.big-quote p{font-family:var(--display);font-weight:700;font-size:clamp(30px,4.2vw,62px);line-height:1.08;letter-spacing:-.02em;max-width:22ch}
.big-quote cite{font-style:normal;display:flex;align-items:center;gap:14px;color:#dfe4ff}
.big-quote cite img{width:56px;height:56px;border-radius:50%;object-fit:cover}

.awards table{width:100%;border-collapse:collapse;font-size:18px}
.awards th{text-align:left;font-size:14px;color:var(--muted);font-weight:700;padding:0 0 12px}
.awards td{padding:20px 0;border-top:1px solid #D8DBF5}
.awards td:first-child{font-family:var(--display);font-weight:700;font-size:22px;color:var(--blue-d)}
.awards td:last-child{text-align:right;color:var(--muted)}
.tw{overflow-x:auto}

.team-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}
.member img{aspect-ratio:3/4;object-fit:cover;border-radius:22px;width:100%;filter:grayscale(1);transition:filter .3s}
.member:hover img{filter:none}
.member h3{font-size:24px;margin-top:14px}.member p{margin:2px 0 0;color:var(--muted);font-size:15px}

.contact{background:var(--pink)}
.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:start}
.contact h2{font-size:clamp(46px,6.4vw,100px)}
.contact .lead{font-size:19px;margin:24px 0}
.contact-list a{display:block;font-family:var(--display);font-weight:700;font-size:26px;color:var(--blue);text-decoration:none;margin-bottom:6px}
form{background:#fff;border-radius:28px;padding:34px}
label{display:block;font-weight:700;font-size:14px;margin-bottom:6px;color:var(--blue-d)}
input,select,textarea{width:100%;font:inherit;padding:13px 15px;border:2px solid #D8DBF5;border-radius:14px;margin-bottom:16px;color:var(--text);background:#fff}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--blue)}
fieldset{border:0;padding:0;margin:0 0 16px}legend{font-weight:700;font-size:14px;margin-bottom:8px;color:var(--blue-d)}
.opts{display:flex;flex-wrap:wrap;gap:8px}
.opts label{margin:0;cursor:pointer}
.opts input{position:absolute;opacity:0;width:1px;height:1px}
.opts span{display:inline-block;border:2px solid #D8DBF5;border-radius:999px;padding:8px 16px;font-weight:600}
.opts input:checked+span{background:var(--blue);color:#fff;border-color:var(--blue)}
.opts input:focus-visible+span{outline:3px solid var(--pink-d)}
form .btn{width:100%;justify-content:center}
footer{background:var(--blue-d);color:#b8c0ff;padding:60px 0 30px;font-size:15px}
.foot{display:flex;justify-content:space-between;gap:30px;flex-wrap:wrap;margin-bottom:40px}
.foot .logo{font-size:60px}
footer ul{list-style:none;padding:0;margin:0;display:flex;gap:26px;flex-wrap:wrap}footer a{text-decoration:none}footer a:hover{color:#fff}
.legal{border-top:1px solid #26308c;padding-top:22px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
@media (max-width:1000px){.menu,.nav>.btn{display:none}.burger{display:block}
.menu.open{display:flex;flex-direction:column;position:absolute;top:84px;left:0;right:0;background:var(--blue);padding:22px 28px 30px;gap:16px;z-index:30}
.site-header{position:relative}
.hero-foot,.contact-grid{grid-template-columns:1fr}.hero-actions{justify-content:flex-start}
.strip{grid-template-columns:1fr 1fr}.strip img:first-child{grid-column:span 2}
.p1,.p2,.p3,.p4{grid-column:span 12;margin-top:0}
.svc-row{grid-template-columns:1fr;gap:12px}
.team-grid{grid-template-columns:1fr 1fr}}
@media (max-width:600px){body{font-size:16px}section{padding:80px 0}.strip{grid-template-columns:1fr}.strip img{height:240px}.strip img:first-child{grid-column:auto}.strip img:not(:first-child){display:none}.team-grid{grid-template-columns:1fr}.foot .logo{font-size:44px}}
